function openSheet(title,content){var overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML='<div class="modal"><div class="modal-handle"></div><div class="modal-header"><div class="modal-title">'+esc(title)+'</div><button class="modal-close" onclick="closeSheet()">✕</button></div>'+content+'</div>';overlay.onclick=function(e){if(e.target===overlay)closeSheet()};document.body.appendChild(overlay);document.body.style.overflow='hidden';playClickSound()}
function closeSheet(){document.querySelectorAll('.overlay').forEach(function(o){o.remove()});document.body.style.overflow='';playClickSound()}
function openThemePicker(){var html='<div class="footnote text-tertiary" style="margin-bottom:8px;">🎨 Обычные</div>';html+='<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:20px;">';THEMES.forEach(function(t){if(t.halloween)return;var active=state.settings.theme===t.id;html+='<button onclick="setTheme(\''+t.id+'\')" style="padding:14px 8px;border-radius:14px;border:2px solid '+(active?'var(--brand)':'transparent')+';background:'+t.color+';color:#fff;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;"><span style="font-size:26px;">'+t.emoji+'</span><span style="font-size:11px;font-weight:700;">'+t.name+'</span></button>'});html+='</div>';html+='<div class="footnote text-tertiary" style="margin-bottom:8px;">🎃 Хэллоуин</div>';html+='<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:20px;">';THEMES.forEach(function(t){if(!t.halloween)return;var active=state.settings.theme===t.id;html+='<button onclick="setTheme(\''+t.id+'\')" style="padding:14px 8px;border-radius:14px;border:2px solid '+(active?'var(--brand)':'transparent')+';background:'+t.color+';color:#fff;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;"><span style="font-size:26px;">'+t.emoji+'</span><span style="font-size:11px;font-weight:700;">'+t.name+'</span></button>'});html+='</div>';html+='<div class="card" style="margin:0;padding:14px 16px;"><div class="row-between"><div><div class="list-title">🌈 Изюминки тем</div><div class="caption text-tertiary">Дождь, звёзды, лепестки</div></div><button class="switch '+(state.settings.effectsEnabled?'on':'')+'" onclick="state.settings.effectsEnabled=!state.settings.effectsEnabled;save();closeSheet();startEffects();toast(\'Ок\',\'success\');playClickSound();"></button></div></div>';openSheet('Тема',html)}
function setTheme(id){state.settings.theme=id;applyTheme(id);save();haptic('success');playClickSound();closeSheet();toast('Тема изменена','success')}
function applyTheme(id){var themes=['dark','light','ocean','sakura','forest','sunset','ice','amethyst','pumpkin','vampire','ghost','web'];themes.forEach(function(t){document.body.classList.remove('theme-'+t)});document.body.classList.add('theme-'+id);startEffects()}
function startEffects(){var overlay=document.getElementById('themeEffect');if(!overlay)return;overlay.innerHTML='';var theme=THEMES.find(function(t){return t.id===state.settings.theme});if(!theme||!state.settings.effectsEnabled)return;var effect=theme.effects;if(effect==='none')return;if(effect==='stars'){for(var i=0;i<12;i++){var s=document.createElement('div');s.className='effect-star';s.style.left=Math.random()*100+'%';s.style.top=Math.random()*100+'%';s.style.animationDelay=Math.random()*3+'s';overlay.appendChild(s)}}else if(effect==='rain'){for(var j=0;j<15;j++){var d=document.createElement('div');d.className='effect-drop';d.style.left=Math.random()*100+'%';d.style.animationDuration=(Math.random()*1.5+1.5)+'s';d.style.animationDelay=Math.random()*5+'s';d.style.height=(Math.random()*20+12)+'px';overlay.appendChild(d)}}else if(effect==='petals'){for(var k=0;k<8;k++){var p=document.createElement('div');p.className='effect-float';p.textContent='🌸';p.style.left=Math.random()*100+'%';p.style.animationDuration=(Math.random()*8+10)+'s';p.style.animationDelay=Math.random()*10+'s';overlay.appendChild(p)}}else if(effect==='leaves'){for(var l=0;l<8;l++){var lf=document.createElement('div');lf.className='effect-float';lf.textContent='🍃';lf.style.left=Math.random()*100+'%';lf.style.animationDuration=(Math.random()*8+8)+'s';lf.style.animationDelay=Math.random()*10+'s';overlay.appendChild(lf)}}else if(effect==='dust'){for(var m=0;m<12;m++){var dm=document.createElement('div');dm.className='effect-star';dm.style.left=Math.random()*100+'%';dm.style.top=Math.random()*100+'%';dm.style.background='rgba(255,184,120,.6)';dm.style.boxShadow='0 0 8px rgba(255,184,120,.8)';dm.style.animationDelay=Math.random()*5+'s';overlay.appendChild(dm)}}else if(effect==='snow'){for(var n=0;n<10;n++){var sn=document.createElement('div');sn.className='effect-float';sn.textContent='❄️';sn.style.left=Math.random()*100+'%';sn.style.animationDuration=(Math.random()*6+8)+'s';sn.style.animationDelay=Math.random()*10+'s';overlay.appendChild(sn)}}else if(effect==='bats'){for(var b=0;b<3;b++){var bat=document.createElement('div');bat.className='effect-fly';bat.textContent='🦇';bat.style.left=Math.random()*100+'%';bat.style.top=Math.random()*50+'%';bat.style.animationDelay=Math.random()*5+'s';overlay.appendChild(bat)}}else if(effect==='ghosts'){for(var g=0;g<3;g++){var gh=document.createElement('div');gh.className='effect-fly';gh.textContent='👻';gh.style.left=Math.random()*100+'%';gh.style.top=Math.random()*50+'%';gh.style.animationDelay=Math.random()*5+'s';overlay.appendChild(gh)}}else if(effect==='spiders'){for(var sp=0;sp<3;sp++){var spd=document.createElement('div');spd.className='effect-fly';spd.textContent='🕷';spd.style.left=Math.random()*100+'%';spd.style.top=Math.random()*50+'%';spd.style.animationDelay=Math.random()*5+'s';overlay.appendChild(spd)}}}
function getLevelProgress(levelId){var level=LEARNING_LEVELS.find(function(l){return l.id===levelId});if(!level)return{done:0,total:0,pct:0};var total=0,done=0;level.modules.forEach(function(mod){mod.lessons.forEach(function(l,idx){total++;if(state.levelProgress&&state.levelProgress[levelId+'_'+mod.id+'_'+idx])done++})});return{done:done,total:total,pct:total>0?Math.round(done/total*100):0}}
function isLevelUnlocked(levelId){var idx=LEARNING_LEVELS.findIndex(function(l){return l.id===levelId});if(idx<=0)return true;var prev=LEARNING_LEVELS[idx-1];return getLevelProgress(prev.id).pct===100}
function isModuleUnlocked(level,moduleIdx){if(moduleIdx===0)return true;var prevMod=level.modules[moduleIdx-1];return prevMod.lessons.every(function(l,idx){return state.levelProgress[level.id+'_'+prevMod.id+'_'+idx]})}
function isLessonUnlocked(level,module,lessonIdx){if(lessonIdx===0)return true;var key=level.id+'_'+module.id+'_'+(lessonIdx-1);return !!state.levelProgress[key]}
function renderDashboard(){var todayTasks=state.tasks.filter(function(t){return t.created_at&&t.created_at.slice(0,10)===today()});var doneToday=todayTasks.filter(function(t){return t.status==='completed'}).length;var hour=new Date().getHours();var greet=hour<6?'Доброй ночи':hour<12?'Доброе утро':hour<18?'Добрый день':'Добрый вечер';var progress=todayTasks.length?Math.round(doneToday/todayTasks.length*100):0;var userName=state.profile.name?', '+state.profile.name:'';var totalDone=0,totalLessons=0;LEARNING_LEVELS.forEach(function(level){var p=getLevelProgress(level.id);totalDone+=p.done;totalLessons+=p.total});var overallPct=totalLessons?Math.round(totalDone/totalLessons*100):0;var html='<div class="page"><div class="title-xl">'+greet+userName+'</div>';html+='<div class="card card-gradient"><div class="row-between" style="margin-bottom:14px;"><div><div style="font-size:13px;opacity:.85;font-weight:600;margin-bottom:6px;">Прогресс дня</div><div style="font-size:40px;font-weight:800;line-height:1;">'+doneToday+'/'+todayTasks.length+'</div></div><div style="font-size:48px;font-weight:800;">'+progress+'%</div></div><div class="progress" style="background:rgba(255,255,255,.25);height:8px;"><div class="progress-fill" style="width:'+progress+'%;background:#fff;"></div></div></div>';html+='<div class="stat-grid mb-4"><div class="stat-item"><div class="stat-value">'+(state.stats.streak||0)+'</div><div class="stat-label">Streak</div></div><div class="stat-item"><div class="stat-value">'+overallPct+'%</div><div class="stat-label">Обучение</div></div><div class="stat-item"><div class="stat-value">'+((state.watched||[]).length)+'</div><div class="stat-label">Досуг</div></div></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(167,139,250,.15),rgba(91,158,255,.1));border-color:rgba(167,139,250,.3);"><h2>🎓 Обучение</h2><div class="footnote text-secondary" style="margin-bottom:12px;">5 уровней + 5 модулей</div><button class="btn btn-primary btn-block" onclick="navigate(\'learning\')">Открыть</button></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(60,220,130,.15),rgba(91,158,255,.1));border-color:rgba(60,220,130,.3);"><h2>🇬🇧 English 125</h2><div class="footnote text-secondary" style="margin-bottom:12px;">A1-C1 с примерами</div><button class="btn btn-primary btn-block" onclick="navigate(\'english\')">Продолжить</button></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,123,169,.15),rgba(255,169,64,.1));border-color:rgba(255,123,169,.3);"><h2>🎬 Досуг</h2><div class="footnote text-secondary" style="margin-bottom:12px;">Фильмы, книги, игры</div><button class="btn btn-primary btn-block" onclick="navigate(\'entertainment\')">Открыть</button></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,107,107,.15),rgba(255,169,64,.1));border-color:rgba(255,107,107,.3);"><h2>📱 Детокс</h2><div class="footnote text-secondary" style="margin-bottom:12px;">80+ советов</div><button class="btn btn-primary btn-block" onclick="navigate(\'screentracker\')">Открыть</button></div>';if(!state.profile.surveyDone){html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,169,64,.15),rgba(255,107,107,.1));border-color:rgba(255,169,64,.3);"><h2>📋 Заполни профиль</h2><button class="btn btn-primary btn-block" onclick="startSurvey()">Начать</button></div>'}html+='<div class="insight-card"><div class="insight-title">💎 Мудрость дня</div><div class="insight-text">"Ты не ленивый. Ты либо устал, либо не видишь смысла, либо боишься."</div></div>';html+='<div class="card"><h2>⚡ Быстрые действия</h2><div class="btn-row"><button class="btn btn-ghost btn-sm" onclick="navigate(\'domains\')">🌐 Домены</button><button class="btn btn-ghost btn-sm" onclick="addTask()">➕ Задача</button><button class="btn btn-ghost btn-sm" onclick="navigate(\'matrix\')">🔢 Матрица</button><button class="btn btn-ghost btn-sm" onclick="navigate(\'more\')">⋯ Ещё</button></div></div>';html+='<div class="card"><h2>📋 Задачи</h2>';var pending=state.tasks.filter(function(t){return t.status==='pending'}).slice(0,5);if(pending.length){pending.forEach(function(t){html+=taskRow(t)})}else{html+='<div class="empty"><div class="empty-icon">✨</div><div class="empty-title">Всё выполнено</div></div>'}html+='</div></div>';document.getElementById('app').innerHTML=html}
function taskRow(t){var pColors={high:'high',medium:'medium',low:'low'};var checked=t.status==='completed';return '<div class="task-item '+(checked?'completed':'')+'" onclick="editTask(\''+t.id+'\')"><div class="priority-bar '+(pColors[t.priority]||'medium')+'"></div><button class="task-checkbox '+(checked?'checked':'')+'" onclick="event.stopPropagation();toggleTask(\''+t.id+'\')">'+(checked?'✓':'')+'</button><div class="task-content"><div class="task-title">'+esc(t.title)+'</div><div class="task-meta"><span>'+(t.planned_time||0)+' мин</span>'+(t.category?'<span>· '+esc(t.category)+'</span>':'')+'</div></div></div>'}
var taskFilter='all';var taskSearch='';
function renderTasks(){var counts={all:state.tasks.length,pending:state.tasks.filter(function(t){return t.status==='pending'}).length,completed:state.tasks.filter(function(t){return t.status==='completed'}).length};var filtered=state.tasks.slice();if(taskFilter!=='all')filtered=filtered.filter(function(t){return t.status===taskFilter});if(taskSearch){var q=taskSearch.toLowerCase();filtered=filtered.filter(function(t){return t.title.toLowerCase().indexOf(q)>=0})}var html='<div class="page"><div class="row-between" style="margin-bottom:20px;"><div class="title-xl" style="margin:0;">Задачи</div><button class="btn btn-primary btn-sm" onclick="addTask()">+ Новая</button></div>';html+='<div class="search-bar"><span style="color:var(--text-3);font-size:18px;">🔍</span><input type="search" placeholder="Поиск..." value="'+esc(taskSearch)+'" oninput="taskSearch=this.value;renderTasks()"/></div>';html+='<div class="segmented" style="margin-bottom:18px;"><button class="segmented-item '+(taskFilter==='all'?'active':'')+'" onclick="taskFilter=\'all\';renderTasks()">Все ('+counts.all+')</button><button class="segmented-item '+(taskFilter==='pending'?'active':'')+'" onclick="taskFilter=\'pending\';renderTasks()">Активные ('+counts.pending+')</button><button class="segmented-item '+(taskFilter==='completed'?'active':'')+'" onclick="taskFilter=\'completed\';renderTasks()">Готовые ('+counts.completed+')</button></div>';if(filtered.length){filtered.forEach(function(t){html+=taskRow(t)})}else{html+='<div class="empty"><div class="empty-icon">📋</div><div class="empty-title">'+(taskSearch?'Ничего':'Нет задач')+'</div></div>'}html+='</div>';document.getElementById('app').innerHTML=html}
function addTask(){openSheet('Новая задача','<div class="field"><input type="text" id="t-title" placeholder="Название" autofocus/></div><div class="row" style="gap:8px;"><div style="flex:1;"><label class="field-label">Время</label><input type="number" id="t-time" value="30" min="5" step="5"/></div><div style="flex:1;"><label class="field-label">Приоритет</label><select id="t-priority"><option value="low">🟢</option><option value="medium" selected>🟡</option><option value="high">🔴</option></select></div></div><button class="btn btn-primary btn-block mt-3" onclick="saveTask()">Добавить</button>');setTimeout(function(){var el=document.getElementById('t-title');if(el)el.focus()},100)}
function saveTask(){var title=((document.getElementById('t-title')||{}).value||'').trim();if(!title)return toast('Введите название','error');state.tasks.unshift({id:uid(),title:title,planned_time:parseInt((document.getElementById('t-time')||{}).value)||30,actual_time:0,status:'pending',priority:(document.getElementById('t-priority')||{}).value||'medium',category:'Работа',created_at:nowISO()});save();playSuccessSound();closeSheet();toast('Задача добавлена','success');haptic('success');checkAchievements();if(currentPage==='tasks')renderTasks();else renderDashboard()}
function toggleTask(id){var t=state.tasks.find(function(x){return x.id===id});if(!t)return;t.status=t.status==='completed'?'pending':'completed';t.actual_time=t.status==='completed'?(t.planned_time||0):0;save();if(t.status==='completed'){playSuccessSound();toast('✓ Выполнено','success')}else{playClickSound()}haptic('success');checkAchievements();if(currentPage==='tasks')renderTasks();else renderDashboard()}
function editTask(id){var t=state.tasks.find(function(x){return x.id===id});if(!t)return;openSheet('Редактировать','<div class="field"><input type="text" id="e-title" value="'+esc(t.title)+'"/></div><button class="btn btn-primary btn-block" onclick="updateTask(\''+id+'\')">Сохранить</button><button class="btn btn-danger btn-block mt-2" onclick="deleteTask(\''+id+'\')">Удалить</button>')}
function updateTask(id){var t=state.tasks.find(function(x){return x.id===id});if(!t)return;t.title=(document.getElementById('e-title')||{}).value||t.title;save();playSuccessSound();closeSheet();toast('Сохранено','success');renderTasks()}
function deleteTask(id){if(!confirm('Удалить?'))return;state.tasks=state.tasks.filter(function(t){return t.id!==id});save();playErrorSound();closeSheet();toast('Удалено','info');renderTasks()}
function renderLearning(){var totalDone=0,totalLessons=0;LEARNING_LEVELS.forEach(function(level){var p=getLevelProgress(level.id);totalDone+=p.done;totalLessons+=p.total});var overallPct=totalLessons?Math.round(totalDone/totalLessons*100):0;var html='<div class="page"><div class="title-xl">🎓 Обучение</div>';html+='<div class="card card-gradient"><div style="opacity:.9;font-size:13px;margin-bottom:6px;">Общий прогресс</div><div style="font-size:44px;font-weight:800;line-height:1;margin-bottom:12px;">'+overallPct+'%</div><div style="opacity:.9;font-size:13px;">'+totalDone+' из '+totalLessons+'</div><div class="progress" style="margin-top:14px;background:rgba(255,255,255,.25);height:8px;"><div class="progress-fill" style="width:'+overallPct+'%;background:#fff;"></div></div></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(167,139,250,.15),rgba(91,158,255,.1));border-color:rgba(167,139,250,.3);"><h2>🌱 5 уровней</h2><div class="footnote text-secondary" style="margin-bottom:12px;">От новичка до наставника</div><button class="btn btn-primary btn-block" onclick="navigate(\'levels\')">Открыть</button></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(179,148,255,.15),rgba(91,158,255,.1));border-color:rgba(179,148,255,.3);"><h2>🧠 Память</h2><div class="footnote text-secondary" style="margin-bottom:12px;">10 уроков</div><button class="btn btn-primary btn-block" onclick="navigate(\'memory\')">Открыть</button></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(77,212,255,.15),rgba(91,158,255,.1));border-color:rgba(77,212,255,.3);"><h2>🎯 IQ</h2><div class="footnote text-secondary" style="margin-bottom:12px;">10 уроков</div><button class="btn btn-primary btn-block" onclick="navigate(\'iq\')">Открыть</button></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,107,107,.15),rgba(255,169,64,.1));border-color:rgba(255,107,107,.3);"><h2>❤️ EQ</h2><div class="footnote text-secondary" style="margin-bottom:12px;">10 уроков</div><button class="btn btn-primary btn-block" onclick="navigate(\'eq\')">Открыть</button></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,204,77,.15),rgba(255,169,64,.1));border-color:rgba(255,204,77,.3);"><h2>💰 Финансы</h2><div class="footnote text-secondary" style="margin-bottom:12px;">10 уроков</div><button class="btn btn-primary btn-block" onclick="navigate(\'finance\')">Открыть</button></div>';html+='<div class="card" style="background:linear-gradient(135deg,rgba(61,220,151,.15),rgba(91,158,255,.1));border-color:rgba(61,220,151,.3);"><h2>🔬 Нейро</h2><div class="footnote text-secondary" style="margin-bottom:12px;">10 уроков</div><button class="btn btn-primary btn-block" onclick="navigate(\'neuromodule\')">Открыть</button></div>';html+='<div class="card"><h2>🗺 Пути</h2><button class="btn btn-ghost btn-block" onclick="navigate(\'paths\')">Открыть</button></div>';html+='<div class="card"><h2>📚 Курсы</h2><button class="btn btn-ghost btn-block" onclick="navigate(\'courses\')">Открыть</button></div>';html+='<div class="card"><h2>💎 Методики</h2><button class="btn btn-ghost btn-block" onclick="navigate(\'methods\')">Открыть</button></div>';html+='</div>';document.getElementById('app').innerHTML=html}
function renderLevels(){var html='<div class="page"><button class="btn btn-ghost btn-sm" onclick="navigate(\'learning\')" style="margin-bottom:16px;">← Обучение</button><div class="title-xl">🌱 5 уровней</div>';LEARNING_LEVELS.forEach(function(level){var p=getLevelProgress(level.id);var unlocked=isLevelUnlocked(level.id);var completed=p.pct===100;var cls='level-card';if(completed)cls+=' completed';else if(!unlocked)cls+=' locked';else if(p.pct>0)cls+=' active';html+='<div class="'+cls+'" onclick="'+(unlocked?'openLevel(\''+level.id+'\')':'toast(\'Заверши предыдущий\',\'warning\')')+'"><div class="level-header"><div class="level-num">'+(completed?'✓':level.num)+'</div><div class="level-info"><div class="level-title">'+level.emoji+' '+level.title+'</div><div class="level-subtitle">'+level.subtitle+'</div><div class="level-meta"><span>'+level.modules.length+' модулей</span></div></div></div><div class="level-desc">'+level.desc+'</div>';if(unlocked&&p.pct>0)html+='<div class="progress"><div class="progress-fill" style="width:'+p.pct+'%;"></div></div>';html+='</div>'});html+='</div>';document.getElementById('app').innerHTML=html}
