function renderModuleDetail(){var level=LEARNING_LEVELS.find(function(l){return l.id===currentLevelId});if(!level){navigate('learning');return}var module=level.modules.find(function(m){return m.id===currentModuleId});if(!module){navigate('levelDetail');return}var doneCount=module.lessons.filter(function(l,idx){return state.levelProgress[level.id+'_'+module.id+'_'+idx]}).length;var html='<div class="page">';html+='<button class="btn btn-ghost btn-sm" onclick="navigate(\'levelDetail\')" style="margin-bottom:16px;">← К модулям</button>';html+='<div style="text-align:center;margin-bottom:24px;"><div style="font-size:56px;margin-bottom:12px;">'+module.emoji+'</div><div class="title-xl" style="margin-bottom:8px;">'+module.title+'</div><div class="footnote text-secondary" style="max-width:340px;margin:0 auto;">'+module.desc+'</div></div>';html+='<div class="card"><div class="row-between mb-2"><span class="subhead">Прогресс</span><span class="subhead text-secondary">'+doneCount+'/'+module.lessons.length+'</span></div><div class="progress"><div class="progress-fill" style="width:'+Math.round(doneCount/module.lessons.length*100)+'%;"></div></div></div>';html+='<div class="card"><h2>📖 Уроки</h2>';module.lessons.forEach(function(lesson,i){var key=level.id+'_'+module.id+'_'+i;var isDone=!!state.levelProgress[key];var unlocked=isLessonUnlocked(level,module,i);var cls='lesson-row';if(isDone)cls+=' done';else if(!unlocked)cls+=' locked';else cls+=' current';html+='<div class="'+cls+'" onclick="'+(unlocked?'openLesson('+i+')':'toast(\'Сначала предыдущий\',\'warning\')')+'"><div class="lesson-num">'+(isDone?'✓':(i+1))+'</div><div class="lesson-title">'+lesson.title+'</div><div style="color:var(--text-4);font-size:20px;">›</div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function openLesson(idx){currentLessonIdx=idx;var level=LEARNING_LEVELS.find(function(l){return l.id===currentLevelId});if(!level)return;var module=level.modules.find(function(m){return m.id===currentModuleId});if(!module)return;var lesson=module.lessons[idx];if(!lesson)return;var key=level.id+'_'+module.id+'_'+idx;var isDone=!!state.levelProgress[key];var html='<div class="page">';html+='<button class="btn btn-ghost btn-sm" onclick="navigate(\'moduleDetail\')" style="margin-bottom:16px;">← К урокам</button>';html+='<div style="margin-bottom:20px;"><div class="footnote text-tertiary" style="margin-bottom:8px;">Уровень '+level.num+' · '+module.title+' · Урок '+(idx+1)+'/'+module.lessons.length+'</div><div style="font-size:26px;font-weight:800;line-height:1.2;">'+lesson.title+'</div></div>';html+='<div class="card" style="padding:20px;">';html+='<div class="lesson-section"><div class="lesson-section-title">📚 Теория</div><div class="lesson-content">'+formatLesson(lesson.theory)+'</div></div>';html+='<div class="lesson-section practice"><div class="lesson-section-title">🎯 Практика</div><div class="lesson-content">'+esc(lesson.practice)+'</div></div>';html+='<div class="lesson-section reflection"><div class="lesson-section-title">💭 Рефлексия</div><div class="lesson-content">'+esc(lesson.reflection)+'</div></div>';html+='</div>';if(!isDone){html+='<button class="btn btn-primary btn-block" onclick="completeLesson()">✓ Изучено</button>'}else{html+='<div class="badge badge-success" style="display:block;text-align:center;padding:14px;font-size:14px;">✓ Урок изучен</div>';if(idx<module.lessons.length-1){html+='<button class="btn btn-primary btn-block mt-3" onclick="openLesson('+(idx+1)+')">Следующий →</button>'}else{html+='<button class="btn btn-success btn-block mt-3" onclick="navigate(\'moduleDetail\')">Модуль завершён ✓</button>'}}html+='</div>';document.getElementById('app').innerHTML=html;window.scrollTo({top:0})}
function formatLesson(text){var h=esc(text);h=h.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');h=h.replace(/^• (.+)$/gm,'<li>$1</li>');h=h.replace(/(<li>[\s\S]*?<\/li>)(?!\s*<li>)/g,'<ul>$1</ul>');h=h.replace(/\n\n/g,'</p><p>');h=h.replace(/\n/g,'<br>');return '<p>'+h+'</p>'}
