function renderPaths(){var html='<div class="page"><div class="title-xl">🗺 Пути</div>';PATHS_LIBRARY.forEach(function(p){var userPath=state.paths.find(function(x){return x.id===p.id});var completed=userPath?(userPath.completedSteps||[]).length:0;var progress=Math.round(completed/p.steps.length*100);html+='<div class="card" style="cursor:pointer;" onclick="openPath(\''+p.id+'\')"><div style="display:flex;gap:14px;align-items:center;margin-bottom:12px;"><div style="width:56px;height:56px;border-radius:18px;background:var(--surface-3);display:grid;place-items:center;font-size:28px;flex-shrink:0;">'+p.emoji+'</div><div style="flex:1;"><div style="font-size:17px;font-weight:800;margin-bottom:4px;">'+p.title+'</div><div class="footnote text-secondary">'+completed+'/'+p.steps.length+' · '+p.category+'</div></div><div class="list-chevron">›</div></div><div class="progress"><div class="progress-fill" style="width:'+progress+'%;"></div></div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openPath(id){currentPathId=id;navigate('pathDetail')}
function renderPathDetail(){var p=PATHS_LIBRARY.find(function(x){return x.id===currentPathId});if(!p){navigate('paths');return}var userPath=state.paths.find(function(x){return x.id===p.id});if(!userPath){userPath={id:p.id,completedSteps:[],startedAt:nowISO()};state.paths.push(userPath);save()}var completed=userPath.completedSteps||[];var progress=Math.round(completed.length/p.steps.length*100);var html='<div class="page"><button class="btn btn-ghost btn-sm" onclick="navigate(\'paths\')" style="margin-bottom:16px;">← Все пути</button>';html+='<div style="text-align:center;margin-bottom:24px;"><div style="font-size:64px;margin-bottom:12px;">'+p.emoji+'</div><div class="title-xl">'+p.title+'</div></div>';html+='<div class="card"><div class="row-between mb-2"><span class="subhead">Прогресс</span><span class="subhead text-secondary">'+progress+'%</span></div><div class="progress"><div class="progress-fill" style="width:'+progress+'%;"></div></div></div>';html+='<div class="card"><h2>Шаги</h2>';p.steps.forEach(function(step,i){var isDone=completed.indexOf(i)>=0;var isActive=!isDone&&(i===0||completed.indexOf(i-1)>=0);var isLocked=!isDone&&!isActive;var cls='path-step';if(isDone)cls+=' completed';else if(isActive)cls+=' active';else if(isLocked)cls+=' locked';html+='<div class="'+cls+'" onclick="'+(isLocked?'':'openStep('+i+')')+'"><div class="path-step-num">'+(isDone?'✓':(i+1))+'</div><div class="path-step-body"><div class="path-step-title">'+step.title+'</div><div class="path-step-desc">'+(isDone||isActive?step.desc:'🔒')+'</div></div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function openStep(idx){var p=PATHS_LIBRARY.find(function(x){return x.id===currentPathId});if(!p)return;var step=p.steps[idx];if(!step)return;var userPath=state.paths.find(function(x){return x.id===p.id});var isDone=userPath&&(userPath.completedSteps||[]).indexOf(idx)>=0;var html='<div class="card"><h2>📋 Задача</h2><div style="font-size:15px;line-height:1.6;">'+step.desc+'</div></div>';html+='<div class="insight-card"><div class="insight-title">💎 Секрет</div><div class="insight-text">'+step.secret+'</div></div>';if(!isDone){html+='<button class="btn btn-primary btn-block mt-4" onclick="completeStep('+idx+')">✓ Отметить</button>'}else{html+='<div class="badge badge-success" style="display:block;text-align:center;padding:12px;">✓ Выполнено</div>'}openSheet(step.title,html)}
function completeStep(idx){var userPath=state.paths.find(function(x){return x.id===currentPathId});if(!userPath)return;if(!userPath.completedSteps)userPath.completedSteps=[];if(userPath.completedSteps.indexOf(idx)<0){userPath.completedSteps.push(idx);save();playSuccessSound();toast('✓ Шаг выполнен!','success');haptic('success');checkAchievements();closeSheet();renderPathDetail()}}
function renderCourses(){var html='<div class="page"><div class="title-xl">📚 Курсы</div>';COURSES_LIBRARY.forEach(function(c){var userCourse=state.courses.find(function(x){return x.id===c.id});var completed=userCourse?(userCourse.completedLessons||[]).length:0;var progress=Math.round(completed/c.lessons.length*100);html+='<div class="course-card" onclick="openCourse(\''+c.id+'\')"><div class="course-header"><div class="course-emoji">'+c.emoji+'</div><div class="course-info"><div class="course-title">'+c.title+'</div><div class="course-meta">'+completed+'/'+c.lessons.length+' · '+progress+'%</div></div></div><div class="progress"><div class="progress-fill" style="width:'+progress+'%;"></div></div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openCourse(id){var c=COURSES_LIBRARY.find(function(x){return x.id===id});if(!c)return;var userCourse=state.courses.find(function(x){return x.id===id});if(!userCourse){userCourse={id:id,completedLessons:[],startedAt:nowISO()};state.courses.push(userCourse);save()}var completed=userCourse.completedLessons||[];var progress=Math.round(completed.length/c.lessons.length*100);var html='<div class="page"><button class="btn btn-ghost btn-sm" onclick="navigate(\'courses\')" style="margin-bottom:16px;">← Курсы</button>';html+='<div style="text-align:center;margin-bottom:24px;"><div style="font-size:64px;margin-bottom:12px;">'+c.emoji+'</div><div class="title-xl">'+c.title+'</div></div>';html+='<div class="card"><div class="row-between mb-2"><span class="subhead">Прогресс</span><span class="subhead text-secondary">'+completed.length+'/'+c.lessons.length+'</span></div><div class="progress"><div class="progress-fill" style="width:'+progress+'%;"></div></div></div>';html+='<div class="card"><h2>📚 Уроки</h2>';c.lessons.forEach(function(lesson,i){var isDone=completed.indexOf(i)>=0;html+='<div class="lesson-row '+(isDone?'done':'')+'" onclick="openCourseLesson(\''+c.id+'\','+i+')"><div class="lesson-num">'+(isDone?'✓':(i+1))+'</div><div class="lesson-title">'+lesson.title+'</div><div style="color:var(--text-4);font-size:20px;">›</div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function openCourseLesson(courseId,idx){var c=COURSES_LIBRARY.find(function(x){return x.id===courseId});if(!c)return;var lesson=c.lessons[idx];if(!lesson)return;var userCourse=state.courses.find(function(x){return x.id===courseId});var isDone=userCourse&&(userCourse.completedLessons||[]).indexOf(idx)>=0;var html='<div style="margin-bottom:16px;"><div class="footnote text-tertiary" style="margin-bottom:8px;">Урок '+(idx+1)+'/'+c.lessons.length+'</div><div style="font-size:22px;font-weight:800;">'+lesson.title+'</div></div>';html+='<div class="card"><div style="font-size:15px;line-height:1.7;">'+esc(lesson.content)+'</div></div>';if(!isDone){html+='<button class="btn btn-primary btn-block mt-3" onclick="completeCourseLesson(\''+courseId+'\','+idx+')">✓ Изучено</button>'}else{html+='<div class="badge badge-success" style="display:block;text-align:center;padding:12px;">✓ Изучено</div>'}openSheet(lesson.title,html)}
function completeCourseLesson(courseId,idx){var userCourse=state.courses.find(function(x){return x.id===courseId});if(!userCourse)return;if(!userCourse.completedLessons)userCourse.completedLessons=[];if(userCourse.completedLessons.indexOf(idx)<0){userCourse.completedLessons.push(idx);save();playSuccessSound();toast('✓ Урок изучен!','success');haptic('success');checkAchievements();closeSheet();openCourse(courseId)}}
function renderMethods(){var html='<div class="page"><div class="title-xl">💎 Методики</div><div class="footnote text-secondary" style="margin-bottom:16px;">'+METHODS_LIBRARY.length+' техник.</div>';METHODS_LIBRARY.forEach(function(m){html+='<div class="method-card" onclick="openMethod(\''+m.id+'\')"><div class="method-header"><div class="method-emoji">'+m.emoji+'</div><div style="flex:1;min-width:0;"><div class="method-title">'+m.title+'</div><div class="method-cat">'+m.category+'</div></div><div class="list-chevron">›</div></div><div class="method-desc">'+m.desc+'</div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openMethod(id){var m=METHODS_LIBRARY.find(function(x){return x.id===id});if(!m)return;var html='<div style="text-align:center;margin-bottom:20px;"><div style="font-size:56px;margin-bottom:12px;">'+m.emoji+'</div><div style="font-size:22px;font-weight:800;margin-bottom:6px;">'+m.title+'</div><div class="footnote text-secondary">'+m.category+'</div></div>';html+='<div class="card"><div class="footnote text-secondary">'+m.desc+'</div></div>';html+='<div class="card"><h2>📋 Шаги</h2>';m.steps.forEach(function(step,i){html+='<div style="display:flex;gap:12px;padding:8px 0;"><div style="width:24px;height:24px;border-radius:50%;background:var(--brand);color:#fff;display:grid;place-items:center;flex-shrink:0;font-size:12px;font-weight:700;">'+(i+1)+'</div><div style="flex:1;font-size:14px;line-height:1.5;">'+step+'</div></div>'});html+='</div>';html+='<div class="insight-card"><div class="insight-title">🔬 База</div><div class="insight-text">'+m.base+'</div></div>';openSheet(m.title,html)}
function getAverageDomainScore(domainId){var history=state.domainHistory||{};var dates=Object.keys(history).slice(-7);if(dates.length===0)return 5;var sum=0,count=0;dates.forEach(function(d){if(history[d]&&history[d][domainId]!==undefined){sum+=history[d][domainId];count++}});return count>0?Math.round(sum/count*10)/10:5}
function renderDomains(){var html='<div class="page"><div class="title-xl">🌐 9 доменов</div><div class="footnote text-secondary" style="margin-bottom:16px;">Оцени 1-10. План строится автоматически.</div>';var todayScores=(state.domainScores||{})[today()]||{};var totalScore=0,count=0;DOMAINS.forEach(function(d){if(todayScores[d.id]){totalScore+=todayScores[d.id];count++}});var avg=count>0?Math.round(totalScore/count*10)/10:0;html+='<div class="card card-gradient"><div style="opacity:.9;font-size:13px;margin-bottom:6px;">Средний балл</div><div style="font-size:44px;font-weight:800;line-height:1;">'+avg+'/10</div><div style="opacity:.9;font-size:13px;margin-top:8px;">'+count+' из 9 оценено</div></div>';DOMAINS.forEach(function(d){var score=todayScores[d.id]||0;var pct=score*10;var avgScore=getAverageDomainScore(d.id);html+='<div class="domain-card" onclick="openDomain(\''+d.id+'\')"><div class="domain-header"><div class="domain-icon" style="background:'+d.color+'20;color:'+d.color+';">'+d.emoji+'</div><div style="flex:1;min-width:0;"><div class="domain-title">'+d.name+'</div><div class="domain-score">'+(score>0?'Сегодня: '+score+'/10':'Не оценено')+(avgScore>0?' · Среднее: '+avgScore:'')+'</div></div><div class="list-chevron">›</div></div><div class="domain-bar"><div class="domain-bar-fill" style="width:'+pct+'%;background:'+d.color+';"></div></div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openDomain(domainId){var d=DOMAINS.find(function(x){return x.id===domainId});if(!d)return;var todayScores=(state.domainScores||{})[today()]||{};var score=todayScores[domainId]||5;var html='<div style="text-align:center;margin-bottom:20px;"><div style="font-size:56px;margin-bottom:12px;">'+d.emoji+'</div><div style="font-size:22px;font-weight:800;margin-bottom:6px;">'+d.name+'</div><div class="footnote text-secondary">'+d.desc+'</div></div>';html+='<div class="card"><h2>Оцени сегодня</h2><div style="text-align:center;padding:16px 0;"><div style="font-size:48px;font-weight:800;color:'+d.color+';" id="domainScoreDisplay">'+score+'</div><div class="footnote text-secondary">из 10</div></div><input type="range" min="1" max="10" value="'+score+'" style="width:100%;margin:12px 0;" oninput="document.getElementById(\'domainScoreDisplay\').textContent=this.value;" id="domainScoreRange"/><button class="btn btn-primary btn-block" onclick="saveDomainScore(\''+domainId+'\')">Сохранить</button></div>';html+='<div class="card"><h2>📊 Метрики</h2>';d.metrics.forEach(function(m){var todayMetrics=(state.metrics||{})[today()]||{};var val=todayMetrics[m.id]||'—';html+='<div class="metric-row"><div><div class="metric-label">'+m.label+'</div><div class="metric-target">Цель: '+m.target+'</div></div><div class="metric-value">'+val+'</div></div>'});html+='</div>';openSheet(d.name,html)}
function saveDomainScore(domainId){var range=document.getElementById('domainScoreRange');if(!range)return;var score=parseInt(range.value);var t=today();if(!state.domainScores)state.domainScores={};if(!state.domainScores[t])state.domainScores[t]={};state.domainScores[t][domainId]=score;if(!state.domainHistory)state.domainHistory={};if(!state.domainHistory[t])state.domainHistory[t]={};state.domainHistory[t][domainId]=score;save();playSuccessSound();toast('✓ Сохранено','success');haptic('success');closeSheet();renderDomains()}
function renderMetrics(){var html='<div class="page"><div class="title-xl">📏 Метрики</div><div class="footnote text-secondary" style="margin-bottom:16px;">Все показатели за сегодня.</div>';var todayMetrics=(state.metrics||{})[today()]||{};DOMAINS.forEach(function(d){html+='<div class="metric-card"><div class="metric-card-title">'+d.emoji+' '+d.name+'</div>';d.metrics.forEach(function(m){var val=todayMetrics[m.id]||'';html+='<div class="metric-input-row"><label>'+m.label+'</label><input type="text" id="m_'+m.id+'" value="'+esc(val)+'" placeholder="'+m.target+'"/></div>'});html+='</div>'});html+='<button class="btn btn-primary btn-block" onclick="saveMetrics()">💾 Сохранить</button></div>';document.getElementById('app').innerHTML=html}
function saveMetrics(){var t=today();if(!state.metrics)state.metrics={};if(!state.metrics[t])state.metrics[t]={};DOMAINS.forEach(function(d){d.metrics.forEach(function(m){var el=document.getElementById('m_'+m.id);if(el&&el.value)state.metrics[t][m.id]=el.value})});save();playSuccessSound();toast('💾 Сохранено','success');haptic('success')}
function renderPersonalPlan(){var plan=state.profile.personalPlan;if(!plan){return placeholderPage('🎯','Персональный план','Пройди опросник в профиле')}var html='<div class="page"><div class="title-xl">Твой план</div>';html+='<div class="insight-card"><div class="insight-title">✨ Фокус</div><div class="insight-text">'+plan.focusDomains.map(function(d){var dom=DOMAINS.find(function(x){return x.id===d});return dom?dom.emoji+' '+dom.name:d}).join(', ')+'</div></div>';plan.days.forEach(function(block){html+='<div class="card"><h2>'+block.title+'</h2>';block.items.forEach(function(item){html+='<div class="plan-day"><div class="plan-time">'+item.time+'</div><div class="plan-title">'+item.title+'</div><div class="plan-desc">'+item.desc+'</div></div>'});html+='</div>'});if(plan.metrics.length){html+='<div class="card"><h2>📏 Метрики</h2>';plan.metrics.forEach(function(m){html+='<div class="footnote text-secondary" style="margin-bottom:8px;font-weight:700;">'+m.domain+'</div>';m.items.forEach(function(item){html+='<div class="metric-row"><span class="metric-label">'+item.label+'</span><span class="metric-value">'+item.target+'</span></div>'})});html+='</div>'}html+='<button class="btn btn-ghost btn-block" onclick="navigate(\'metrics\')">📏 Заполнить метрики</button></div>';document.getElementById('app').innerHTML=html}
function renderProfile(){var p=state.profile;var unlocked=p.achievements||[];var doneTasks=state.tasks.filter(function(t){return t.status==='completed'}).length;var lessonsDone=Object.keys(state.levelProgress||{}).length;var html='<div class="page"><div class="profile-hero"><div class="profile-avatar" onclick="pickEmoji()">'+p.emoji+'</div><div class="profile-name">'+esc(p.name||'Пользователь')+'</div></div>';html+='<div class="stat-grid mb-4"><div class="stat-item"><div class="stat-value">'+doneTasks+'</div><div class="stat-label">Задач</div></div><div class="stat-item"><div class="stat-value">'+lessonsDone+'</div><div class="stat-label">Уроков</div></div><div class="stat-item"><div class="stat-value">'+(state.stats.streak||0)+'</div><div class="stat-label">Streak</div></div></div>';html+='<div class="card"><h2>✏️ Имя</h2><div class="field" style="margin-bottom:0;"><input type="text" id="profile-name" value="'+esc(p.name)+'" onchange="saveProfileName(this.value)"/></div></div>';if(!p.surveyDone){html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,169,64,.15),rgba(255,107,107,.1));border-color:rgba(255,169,64,.3);"><h2>📋 Опросник</h2><button class="btn btn-primary btn-block" onclick="startSurvey()">Начать</button></div>'}else{html+='<div class="card"><h2>📋 Профиль заполнен</h2><button class="btn btn-ghost btn-block" onclick="if(confirm(\'Заново?\')){state.profile.surveyDone=false;state.profile.surveyStep=0;save();startSurvey();}">Пройти заново</button></div>'}html+='<div class="card"><h2>🏆 Достижения ('+unlocked.length+'/'+ACHIEVEMENTS.length+')</h2><div class="achieve-grid">';ACHIEVEMENTS.forEach(function(a){var isUnlocked=unlocked.indexOf(a.id)>=0;html+='<div class="achieve-item '+(isUnlocked?'unlocked':'locked')+'"><div class="achieve-icon">'+a.icon+'</div><div class="achieve-name">'+a.name+'</div></div>'});html+='</div></div></div>';document.getElementById('app').innerHTML=html}
function pickEmoji(){var emojis=['😊','😎','🤓','🧑‍💻','👨‍💼','👩‍💼','🦊','🐱','🐶','🦁','🐼','🦉','🌟','⚡','🔥','💎','🚀','🎯','🧠','💪','🌈','☕','🎨','🎮','🎧','📚','🏃','🧘','🍀','🌸'];var html='<div class="emoji-grid">';emojis.forEach(function(e){var sel=e===state.profile.emoji?' selected':'';html+='<button class="emoji-pick'+sel+'" onclick="setEmoji(\''+e+'\')">'+e+'</button>'});html+='</div>';openSheet('Аватар',html)}
