function renderSettings(){var html='<div class="page"><div class="title-xl">⚙️ Настройки</div>';html+='<div class="card"><h2>Профиль</h2><div class="field"><label class="field-label">Имя</label><input type="text" id="s-name" value="'+esc(state.profile.name)+'" onchange="saveProfileName(this.value)"/></div><div class="list-row" onclick="openThemePicker()"><div class="list-icon" style="background:var(--surface-3);">🎨</div><div class="list-body"><div class="list-title">Тема</div></div><div class="list-value">'+(THEMES.find(function(t){return t.id===state.settings.theme})||{}).name+'</div></div></div>';html+='<div class="card"><h2>AI</h2><div class="list-row" onclick="openAISettings()"><div class="list-icon" style="background:var(--brand);">✨</div><div class="list-body"><div class="list-title">'+state.settings.provider+'</div><div class="list-subtitle">'+(state.settings.apiKey?'Ключ установлен':'Не задан')+'</div></div><div class="list-chevron">›</div></div></div>';html+='<div class="card"><h2>Интеграции</h2><div class="list-row" onclick="navigate(\'integrations\')"><div class="list-icon" style="background:var(--surface-3);">🔗</div><div class="list-body"><div class="list-title">Google, Obsidian, Notion, Todoist, Gemini</div></div><div class="list-chevron">›</div></div></div>';html+='<div class="card"><h2>Данные</h2><div class="list-row" onclick="navigate(\'storage\')"><div class="list-icon" style="background:var(--coach);color:#000;">🗄</div><div class="list-body"><div class="list-title">Хранилище</div><div class="list-subtitle">Экспорт, импорт</div></div><div class="list-chevron">›</div></div><div class="list-row" onclick="navigate(\'dbmanager\')"><div class="list-icon" style="background:var(--success);color:#000;">💾</div><div class="list-body"><div class="list-title">База данных</div></div><div class="list-chevron">›</div></div></div>';html+='<div class="footnote text-tertiary" style="text-align:center;margin-top:36px;">AI Health v28</div></div>';document.getElementById('app').innerHTML=html}
function renderDBManager(){var total=state.tasks.length+state.chats.length+state.notes.length+Object.keys(state.levelProgress||{}).length+Object.keys(state.englishProgress||{}).length+(state.entertainment||[]).length+(state.watched||[]).length;var html='<div class="page"><div class="title-xl">💾 База данных</div><div class="card"><div class="list-row"><div class="list-icon" style="background:var(--success);color:#000;">✓</div><div class="list-body"><div class="list-title">LocalStorage</div><div class="list-subtitle">'+STORAGE_KEY+'</div></div></div><div class="list-row"><div class="list-icon" style="background:var(--brand);">📦</div><div class="list-body"><div class="list-title">Записей</div></div><div class="list-value">'+total+'</div></div></div>';html+='<div class="card"><h2>Операции</h2><button class="btn btn-primary btn-block mb-2" onclick="exportDB()">📤 Экспорт</button><button class="btn btn-ghost btn-block mb-2" onclick="document.getElementById(\'importDB\').click()">📥 Импорт</button><input type="file" id="importDB" accept=".json" style="display:none" onchange="importDB(event)"/><button class="btn btn-danger btn-block" onclick="if(confirm(\'Сброс?\')){localStorage.removeItem(\''+STORAGE_KEY+'\');location.reload();}">🗑 Сброс</button></div></div>';document.getElementById('app').innerHTML=html}
