function renderStorage(){var totalSize=0;try{var raw=localStorage.getItem(STORAGE_KEY);totalSize=raw?raw.length:0}catch(e){}var keys=[];try{for(var i=0;i<localStorage.length;i++){var k=localStorage.key(i);if(k&&k.indexOf('ai_health_')===0){keys.push(k)}}}catch(e){}var html='<div class="page"><div class="title-xl">🗄 Хранилище</div>';html+='<div class="card"><h2>💾 Основное</h2><div class="list-row"><div class="list-icon" style="background:var(--success);color:#000;">✓</div><div class="list-body"><div class="list-title">LocalStorage</div><div class="list-subtitle">'+STORAGE_KEY+'</div></div><div class="list-value">'+(totalSize/1024).toFixed(1)+' KB</div></div></div>';if(keys.length){html+='<div class="card"><h2>📂 Все ключи</h2>';keys.forEach(function(k){var val='';try{val=localStorage.getItem(k)||''}catch(e){}html+='<div class="list-row"><div class="list-icon" style="background:var(--surface-3);">🔑</div><div class="list-body"><div class="list-title">'+esc(k)+'</div><div class="list-subtitle">'+(val.length/1024).toFixed(1)+' KB</div></div></div>'});html+='</div>'}html+='<div class="card"><h2>⚙️ Операции</h2><button class="btn btn-primary btn-block mb-2" onclick="exportDB()">📤 Экспорт JSON</button><button class="btn btn-ghost btn-block mb-2" onclick="document.getElementById(\'importDB\').click()">📥 Импорт JSON</button><input type="file" id="importDB" accept=".json" style="display:none" onchange="importDB(event)"/><button class="btn btn-danger btn-block" onclick="if(confirm(\'Сброс?\')){localStorage.removeItem(\''+STORAGE_KEY+'\');location.reload();}">🗑 Полный сброс</button></div></div>';document.getElementById('app').innerHTML=html}
function exportDB(){var blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='ai-health-'+today()+'.json';a.click();URL.revokeObjectURL(url);toast('Экспорт готов','success');playSuccessSound()}
function importDB(e){var file=e.target.files[0];if(!file)return;var reader=new FileReader();reader.onload=function(ev){try{var data=JSON.parse(ev.target.result);if(!confirm('Заменить текущие данные?'))return;state=Object.assign(defaultState(),data);save();toast('Импорт успешен','success');playSuccessSound();location.reload()}catch(err){toast('Ошибка','error');playErrorSound()}};reader.readAsText(file)}
