function renderScreenTracker(){var tips=window.__SCREEN_TIPS||[];var habits=window.__SCREEN_HABITS||[];var html='<div class="page"><div class="title-xl">📱 Экранный детокс</div>';html+='<div class="stat-grid mb-4"><div class="stat-item"><div class="stat-value">'+tips.length+'</div><div class="stat-label">Советов</div></div><div class="stat-item"><div class="stat-value">'+habits.length+'</div><div class="stat-label">Привычек</div></div><div class="stat-item"><div class="stat-value">30</div><div class="stat-label">Дней план</div></div></div>';html+='<div class="card"><h2>🗓 30-дневный план</h2><button class="btn btn-primary btn-block" onclick="navigate(\'detoxplan\')">Открыть</button></div>';var categories={};tips.forEach(function(t){if(!categories[t.category])categories[t.category]=[];categories[t.category].push(t)});Object.keys(categories).forEach(function(cat){html+='<div class="card"><h2>'+cat+'</h2>';categories[cat].forEach(function(t){html+='<div class="screen-card"><div class="screen-title">'+esc(t.title)+'</div><div class="screen-desc">'+esc(t.desc)+'</div><div class="screen-action">→ '+esc(t.action)+'</div><div class="screen-effect">✨ '+esc(t.effect)+' · ⏱ '+esc(t.time)+'</div></div>'});html+='</div>'});html+='</div>';document.getElementById('app').innerHTML=html}
