function renderDailyPlan(){var todayTasks=state.tasks.filter(function(t){return t.status==='pending'});var html='<div class="page"><div class="title-xl">📋 План дня</div>';html+='<div class="card"><h2>🌅 Утро</h2><div class="plan-day"><div class="plan-time">7:30</div><div class="plan-title">Пробуждение</div><div class="plan-desc">Вода + свет</div></div><div class="plan-day"><div class="plan-time">7:45</div><div class="plan-title">Дыхание 4-7-8</div></div><div class="plan-day"><div class="plan-time">8:00</div><div class="plan-title">Движение 15 мин</div></div></div>';html+='<div class="card"><h2>☀️ День</h2><div class="plan-day"><div class="plan-time">9:00</div><div class="plan-title">Deep Work 90 мин</div></div><div class="plan-day"><div class="plan-time">12:00</div><div class="plan-title">Обед</div></div><div class="plan-day"><div class="plan-time">14:00</div><div class="plan-title">Медитация 10 мин</div></div></div>';html+='<div class="card"><h2>🌙 Вечер</h2><div class="plan-day"><div class="plan-time">20:00</div><div class="plan-title">Рефлексия</div></div><div class="plan-day"><div class="plan-time">21:00</div><div class="plan-title">Без экранов</div></div><div class="plan-day"><div class="plan-time">22:30</div><div class="plan-title">Сон</div></div></div>';html+='<div class="card"><h2>📌 Задачи ('+todayTasks.length+')</h2>';todayTasks.slice(0,10).forEach(function(t){html+=taskRow(t)});html+='</div></div>';document.getElementById('app').innerHTML=html}
function renderAI(){var active=state.settings.activePersona||'coach';var persona=PERSONAS[active]||PERSONAS.coach;var messages=state.chats.filter(function(c){return c.persona===active});var hasKey=!!(state.settings.apiKey||(state.integrations.gemini&&state.integrations.gemini.apiKey));var html='<div class="page"><div class="title-xl">✨ AI</div><div class="persona-bar">';Object.keys(PERSONAS).forEach(function(k){var p=PERSONAS[k];html+='<button class="persona-item '+(active===k?'active':'')+'" data-p="'+k+'" onclick="switchPersona(\''+k+'\')">'+p.name+'</button>'});html+='</div>';html+='<div class="card" style="padding:16px 18px;"><div class="row-between"><div class="row" style="gap:12px;"><div style="font-size:28px;">'+persona.emoji+'</div><div><div style="font-weight:700;font-size:16px;">'+persona.name+'</div><div class="caption text-tertiary">'+persona.label+(hasKey?'':' · Demo')+'</div></div></div><button class="btn btn-ghost btn-sm" onclick="openAISettings()">⚙️</button></div></div>';html+='<div class="card" style="min-height:360px;max-height:62vh;overflow-y:auto;padding:18px;" id="chatBox"><div class="chat">';if(messages.length){messages.forEach(function(m){html+='<div class="msg msg-'+(m.role==='user'?'user':'bot')+'">'+(m.role==='user'?esc(m.text):renderMd(m.text))+'</div>'})}else{html+='<div class="empty"><div class="empty-icon">'+persona.emoji+'</div><div class="empty-title">'+persona.name+'</div><div class="empty-text">Задай вопрос</div></div>'}html+='</div></div>';html+='<div class="row" style="margin-top:14px;"><input type="text" id="chatInput" placeholder="Сообщение..." style="flex:1;" onkeydown="if(event.key===\'Enter\'){event.preventDefault();sendMsg();}"/><button class="btn btn-primary btn-icon" onclick="sendMsg()">➤</button></div></div>';document.getElementById('app').innerHTML=html;var box=document.getElementById('chatBox');if(box)box.scrollTop=box.scrollHeight}
function switchPersona(p){state.settings.activePersona=p;save();playClickSound();renderAI()}
async function sendMsg(){var input=document.getElementById('chatInput');if(!input)return;var text=input.value.trim();if(!text)return;input.value='';input.disabled=true;var persona=state.settings.activePersona||'coach';state.chats.push({id:uid(),persona:persona,role:'user',text:text,timestamp:nowISO()});save();playClickSound();renderAI();var box=document.getElementById('chatBox');var typing=document.createElement('div');typing.className='typing';typing.innerHTML='<span></span><span></span><span></span>';if(box){box.appendChild(typing);box.scrollTop=box.scrollHeight}var reply=await callAI(persona,text);if(typing)typing.remove();state.chats.push({id:uid(),persona:persona,role:'coach',text:reply,timestamp:nowISO()});save();checkAchievements();renderAI()}
async function callAI(persona,userText){var key=state.settings.apiKey||(state.integrations.gemini&&state.integrations.gemini.apiKey);var provider=state.settings.provider||'gemini';if(!key)return fallbackReply(persona,userText);var p=PERSONAS[persona];var history=state.chats.filter(function(c){return c.persona===persona}).slice(-10);var messages=[{role:'system',content:p.prompt}];history.forEach(function(m){messages.push({role:m.role==='user'?'user':'assistant',content:m.text})});try{if(provider==='openai'){var resp=await fetch('https://api.openai.com/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({model:'gpt-4o-mini',messages:messages,temperature:.8,max_tokens:800})});var data=await resp.json();return (data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content)||fallbackReply(persona,userText)}else{var sys=p.prompt;var rest=history.map(function(m){return{role:m.role==='user'?'user':'model',parts:[{text:m.text}]}});var model=(state.integrations.gemini&&state.integrations.gemini.model)||'gemini-1.5-flash';var resp3=await fetch('https://generativelanguage.googleapis.com/v1beta/models/'+model+':generateContent?key='+key,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({system_instruction:{parts:[{text:sys}]},contents:rest})});var data3=await resp3.json();return (data3.candidates&&data3.candidates[0]&&data3.candidates[0].content&&data3.candidates[0].content.parts&&data3.candidates[0].content.parts[0]&&data3.candidates[0].content.parts[0].text)||fallbackReply(persona,userText)}}catch(e){console.error(e);return fallbackReply(persona,userText)}}
function fallbackReply(persona,text){text=text||'';if(/суицид|покончить|не хочу жить|умереть/i.test(text)){return '🆘 Позвони: 8-800-2000-122 (РФ) · 103 · findahelpline.com. Ты важен.'}if(persona==='doctor')return 'Я — AI-консультант. Опиши симптомы.\n\n*⚠️ Не заменяет врача.*';if(persona==='psych')return 'Слышу тебя. Что происходит?';return 'Слышу тебя. Расскажи подробнее.'}
function renderMd(text){if(!text)return '';var h=esc(text);h=h.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');h=h.replace(/^[•\-] (.+)$/gm,'<li>$1</li>');h=h.replace(/(<li>[\s\S]*?<\/li>)(?!\s*<li>)/g,'<ul>$1</ul>');h=h.replace(/\n\n/g,'</p><p>');h=h.replace(/\n/g,'<br>');return '<p>'+h+'</p>'}
function openAISettings(){openSheet('Настройки AI','<div class="field"><label class="field-label">Провайдер</label><select id="ai-p"><option value="gemini"'+(state.settings.provider==='gemini'?' selected':'')+'>Google Gemini (бесплатно)</option><option value="openai"'+(state.settings.provider==='openai'?' selected':'')+'>OpenAI</option></select></div><div class="field"><label class="field-label">API ключ</label><input type="password" id="ai-k" value="'+esc(state.settings.apiKey||'')+'"/></div><div class="footnote text-tertiary" style="margin-bottom:14px;">Gemini: <a href="https://aistudio.google.com/app/apikey" target="_blank" style="color:var(--brand);">aistudio.google.com</a></div><button class="btn btn-primary btn-block" onclick="saveAISettings()">Сохранить</button>')}
function saveAISettings(){state.settings.provider=(document.getElementById('ai-p')||{}).value||'gemini';state.settings.apiKey=((document.getElementById('ai-k')||{}).value||'').trim();save();playSuccessSound();closeSheet();toast('Сохранено','success');renderAI()}
function renderHealth(){var waterEntry=state.water.find(function(w){return w.date===today()});var water=waterEntry?waterEntry.count:0;var waterGoal=state.settings.waterGoal||8;var todayScores=(state.domainScores||{})[today()]||{};var html='<div class="page"><div class="title-xl">❤️ Здоровье</div>';html+='<div class="card"><h2>Сегодня</h2><div class="stat-grid"><div class="stat-item" onclick="quickMoodLog()" style="cursor:pointer;"><div class="stat-value">'+(state.mood.length?state.mood[state.mood.length-1].score+'/10':'—')+'</div><div class="stat-label">Настроение</div></div><div class="stat-item" onclick="addWater()" style="cursor:pointer;"><div class="stat-value">'+water+'/'+waterGoal+'</div><div class="stat-label">Вода</div></div><div class="stat-item"><div class="stat-value">'+state.workouts.length+'</div><div class="stat-label">Тренировок</div></div></div></div>';html+='<div class="card"><h2>🌐 Домены</h2>';DOMAINS.forEach(function(d){var score=todayScores[d.id]||0;html+='<div class="list-row" onclick="openDomain(\''+d.id+'\')"><div class="list-icon" style="background:'+d.color+'20;color:'+d.color+';">'+d.emoji+'</div><div class="list-body"><div class="list-title">'+d.name+'</div><div class="list-subtitle">'+(score>0?score+'/10':'Не оценено')+'</div></div><div class="list-chevron">›</div></div>'});html+='</div>';html+='<div class="card"><h2>AI-специалисты</h2>';['doctor','nutrition','fitness','psych'].forEach(function(k){var p=PERSONAS[k];html+='<div class="list-row" onclick="openPersona(\''+k+'\')"><div class="list-icon" style="background:var(--'+p.color+');color:#000;">'+p.emoji+'</div><div class="list-body"><div class="list-title">'+p.name+'</div><div class="list-subtitle">'+p.label+'</div></div><div class="list-chevron">›</div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function openPersona(p){state.settings.activePersona=p;save();playClickSound();navigate('ai')}
function addWater(){var t=today();var entry=state.water.find(function(w){return w.date===t});if(entry)entry.count++;else state.water.push({id:uid(),date:t,count:1,created_at:nowISO()});save();playWaterSound();toast('💧 +1','success');haptic('success');if(currentPage==='dashboard')renderDashboard();else renderHealth()}
function quickMoodLog(){var moods=['😢','😔','😐','🙂','😊'];var html='<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px;">';moods.forEach(function(m,i){html+='<button class="btn btn-ghost" style="font-size:36px;padding:24px 0;" onclick="saveMood('+((i+1)*2)+')">'+m+'</button>'});html+='</div>';openSheet('Настроение?',html)}
function saveMood(score){var t=today();var existing=state.mood.find(function(m){return m.date===t});if(existing)existing.score=score;else state.mood.push({id:uid(),date:t,score:score,created_at:nowISO()});save();playSuccessSound();closeSheet();toast('Записано','success');haptic('success');if(currentPage==='dashboard')renderDashboard();else renderHealth()}
function renderMore(){var groups=[{title:'🌐 Развитие',items:[{key:'domains',emoji:'🌐',label:'9 Доменов'},{key:'metrics',emoji:'📏',label:'Метрики'},{key:'plan',emoji:'🎯',label:'Персональный план'}]},{title:'🎓 Обучение',items:[{key:'learning',emoji:'🎓',label:'5 Уровней + 5 модулей'},{key:'english',emoji:'🇬🇧',label:'Английский 125'},{key:'paths',emoji:'🗺',label:'17 Путей'},{key:'courses',emoji:'📚',label:'12 Курсов'},{key:'methods',emoji:'💎',label:'50+ Методик'}]},{title:'🎬 Досуг',items:[{key:'entertainment',emoji:'🎬',label:'Досуг'},{key:'movies',emoji:'🎥',label:'Фильмы'},{key:'series',emoji:'📺',label:'Сериалы'},{key:'books',emoji:'📚',label:'Книги'},{key:'musiclib',emoji:'🎵',label:'Музыка'},{key:'gameslib',emoji:'🎮',label:'Игры'},{key:'podcastslib',emoji:'🎧',label:'Подкасты'},{key:'watchlist',emoji:'📋',label:'Хочу посмотреть'},{key:'watched',emoji:'✅',label:'Просмотрено'}]},{title:'📅 Планирование',items:[{key:'calendar',emoji:'📅',label:'Календарь'},{key:'stats',emoji:'📊',label:'Статистика'},{key:'matrix',emoji:'🔢',label:'Матрица'},{key:'dailyplan',emoji:'📋',label:'План дня'}]},{title:'🎯 Цели',items:[{key:'habits',emoji:'🔄',label:'Привычки'},{key:'goals',emoji:'🎯',label:'Цели'},{key:'notes',emoji:'📝',label:'Заметки'},{key:'journal',emoji:'📓',label:'Дневник'}]},{title:'❤️ Здоровье',items:[{key:'mood',emoji:'💭',label:'Настроение'},{key:'water',emoji:'💧',label:'Вода'},{key:'meds',emoji:'💊',label:'Лекарства'},{key:'workouts',emoji:'🏋️',label:'Тренировки'},{key:'meditation',emoji:'🧘',label:'Медитации'}]},{title:'🌿 Восстановление',items:[{key:'recovery',emoji:'🌿',label:'Восстановление'},{key:'screentracker',emoji:'📱',label:'Экранный детокс'},{key:'detoxplan',emoji:'🗓',label:'30-дневный план'}]},{title:'📚 Ресурсы',items:[{key:'media',emoji:'📖',label:'Медиатека'},{key:'finance',emoji:'💰',label:'Финансы-модуль'}]},{title:'⚙️ Система',items:[{key:'storage',emoji:'🗄',label:'Хранилище'},{key:'integrations',emoji:'🔗',label:'Интеграции'},{key:'history',emoji:'📋',label:'История'},{key:'dbmanager',emoji:'💾',label:'База данных'},{key:'settings',emoji:'⚙️',label:'Настройки'},{key:'profile',emoji:'👤',label:'Профиль'}]}];var html='<div class="page"><div class="title-xl">Все разделы</div>';groups.forEach(function(g){html+='<div class="card"><h2>'+g.title+'</h2>';g.items.forEach(function(it){html+='<div class="list-row" onclick="navigate(\''+it.key+'\')"><div class="list-icon" style="background:var(--surface-2);">'+it.emoji+'</div><div class="list-body"><div class="list-title">'+it.label+'</div></div><div class="list-chevron">›</div></div>'});html+='</div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function placeholderPage(emoji,name,desc){document.getElementById('app').innerHTML='<div class="page"><div class="title-xl">'+name+'</div><div class="card"><div class="empty"><div class="empty-icon">'+emoji+'</div><div class="empty-title">'+name+'</div><div class="empty-text">'+(desc||'Раздел работает.')+'</div></div></div></div>'}
function renderCalendar(){placeholderPage('📅','Календарь','Google Calendar в разделе Интеграции')}
function renderStats(){var doneTasks=state.tasks.filter(function(t){return t.status==='completed'}).length;var totalLessons=0,doneLessons=0;LEARNING_LEVELS.forEach(function(l){var p=getLevelProgress(l.id);doneLessons+=p.done;totalLessons+=p.total});var html='<div class="page"><div class="title-xl">📊 Статистика</div><div class="stat-grid mb-4"><div class="stat-item"><div class="stat-value">'+doneTasks+'</div><div class="stat-label">Задач</div></div><div class="stat-item"><div class="stat-value">'+doneLessons+'</div><div class="stat-label">Уроков</div></div><div class="stat-item"><div class="stat-value">'+(state.stats.streak||0)+'</div><div class="stat-label">Streak</div></div></div></div>';document.getElementById('app').innerHTML=html}
function renderMatrix(){var matrix={q1:[],q2:[],q3:[],q4:[]};state.tasks.forEach(function(t){if(t.status==='completed')return;var important=t.priority==='high'||t.priority==='medium';var q=important?'q1':'q3';matrix[q].push(t)});var html='<div class="page"><div class="title-xl">🔢 Матрица</div><div class="matrix-grid-2x2"><div class="matrix-quadrant matrix-q1"><div class="matrix-q-title">🔥 Q1</div><div class="matrix-q-count" style="color:var(--danger);">'+matrix.q1.length+'</div></div><div class="matrix-quadrant matrix-q2"><div class="matrix-q-title">📌 Q2</div><div class="matrix-q-count" style="color:var(--brand);">0</div></div><div class="matrix-quadrant matrix-q3"><div class="matrix-q-title">⚡ Q3</div><div class="matrix-q-count" style="color:var(--warning);">'+matrix.q3.length+'</div></div><div class="matrix-quadrant matrix-q4"><div class="matrix-q-title">🗑 Q4</div><div class="matrix-q-count" style="color:var(--text-3);">0</div></div></div></div>';document.getElementById('app').innerHTML=html}
function renderIntegrations(){var g=state.integrations.googleCalendar||{};var o=state.integrations.obsidian||{};var gem=state.integrations.gemini||{};var html='<div class="page"><div class="title-xl">🔗 Интеграции</div>';html+='<div class="integration-card"><div class="integration-header"><div class="integration-icon">📅</div><div style="flex:1;"><div class="integration-title">Google Calendar</div><div class="integration-status">'+(g.connected?'✓':'Не подключено')+'</div></div></div><div class="field mt-3"><label class="field-label">Client ID</label><input type="text" id="gcal-id" value="'+esc(g.clientId||'')+'"/></div><button class="btn btn-primary btn-block" onclick="saveGCal()">💾 Сохранить</button></div>';html+='<div class="integration-card"><div class="integration-header"><div class="integration-icon">🔮</div><div style="flex:1;"><div class="integration-title">Obsidian</div><div class="integration-status">'+(o.apiKey?'✓':'Не подключено')+'</div></div></div><div class="field mt-3"><label class="field-label">API Key</label><input type="password" id="obs-key" value="'+esc(o.apiKey||'')+'"/></div><div class="field"><label class="field-label">Папка</label><input type="text" id="obs-folder" value="'+esc(o.defaultFolder||'AI-Health')+'"/></div><button class="btn btn-primary btn-block" onclick="saveObsidian()">💾 Сохранить</button></div>';html+='<div class="integration-card"><div class="integration-header"><div class="integration-icon">✨</div><div style="flex:1;"><div class="integration-title">Gemini AI</div><div class="integration-status">'+(gem.apiKey?'✓':'Не подключено')+'</div></div></div><div class="field mt-3"><label class="field-label">API Key</label><input type="password" id="gem-key" value="'+esc(gem.apiKey||'')+'"/></div><button class="btn btn-primary btn-block" onclick="saveGemini()">💾 Сохранить</button></div>';html+='</div>';document.getElementById('app').innerHTML=html}
function saveGCal(){state.integrations.googleCalendar.clientId=(document.getElementById('gcal-id')||{}).value||'';state.integrations.googleCalendar.connected=!!state.integrations.googleCalendar.clientId;save();playSuccessSound();toast('Сохранено','success');renderIntegrations()}
function saveObsidian(){state.integrations.obsidian.apiKey=(document.getElementById('obs-key')||{}).value||'';state.integrations.obsidian.defaultFolder=(document.getElementById('obs-folder')||{}).value||'AI-Health';save();playSuccessSound();toast('Сохранено','success');renderIntegrations()}
function saveGemini(){state.integrations.gemini.apiKey=(document.getElementById('gem-key')||{}).value||'';state.integrations.gemini.connected=!!state.integrations.gemini.apiKey;state.settings.apiKey=state.integrations.gemini.apiKey;state.settings.provider='gemini';save();playSuccessSound();toast('Gemini подключён','success');renderIntegrations()}
function startSurvey(){state.profile.surveyStep=0;save();renderSurvey()}
function renderSurvey(){var step=state.profile.surveyStep||0;var q=SURVEY_QUESTIONS[step];if(!q){finishSurvey();return}var answers=state.profile.surveyAnswers||{};var html='<div class="welcome-screen" id="surveyScreen"><div class="survey-container"><div class="survey-progress">';for(var i=0;i<SURVEY_QUESTIONS.length;i++){var cls='survey-dot';if(i<step)cls+=' done';else if(i===step)cls+=' active';html+='<div class="'+cls+'"></div>'}html+='</div>';html+='<div class="survey-question">'+q.question+'</div>';if(q.type==='text'){html+='<input type="text" id="surveyInput" class="welcome-input" style="max-width:100%;text-align:left;font-size:16px !important;" placeholder="Напиши..." value="'+esc(answers[q.id]||'')+'"/><button class="btn btn-primary btn-block mt-3" onclick="saveSurveyAnswer()">Далее →</button>'}else if(q.type==='options'){q.options.forEach(function(opt){var sel=answers[q.id]===opt.value?' selected':'';html+='<div class="survey-option'+sel+'" onclick="selectSurveyOption(\''+q.id+'\',\''+opt.value+'\')"><span class="survey-option-emoji">'+opt.emoji+'</span><span class="survey-option-label">'+opt.label+'</span></div>'})}else if(q.type==='multi'){q.options.forEach(function(opt){var arr=answers[q.id]||[];var sel=arr.indexOf(opt.value)>=0?' selected':'';html+='<div class="survey-option'+sel+'" onclick="toggleSurveyMulti(\''+q.id+'\',\''+opt.value+'\')"><span class="survey-option-emoji">'+opt.emoji+'</span><span class="survey-option-label">'+opt.label+'</span></div>'});html+='<button class="btn btn-primary btn-block mt-3" onclick="nextSurveyStep()">Далее →</button>'}if(step>0){html+='<button class="btn btn-ghost btn-block mt-2" onclick="prevSurveyStep()">← Назад</button>'}html+='</div></div>';var existing=document.getElementById('surveyScreen');if(existing)existing.remove();document.body.insertAdjacentHTML('beforeend',html)}
function selectSurveyOption(qid,val){if(!state.profile.surveyAnswers)state.profile.surveyAnswers={};state.profile.surveyAnswers[qid]=val;save();playClickSound();haptic('light');nextSurveyStep()}
function toggleSurveyMulti(qid,val){if(!state.profile.surveyAnswers)state.profile.surveyAnswers={};var arr=state.profile.surveyAnswers[qid]||[];var idx=arr.indexOf(val);if(idx>=0)arr.splice(idx,1);else arr.push(val);state.profile.surveyAnswers[qid]=arr;save();playClickSound();haptic('light');renderSurvey()}
function saveSurveyAnswer(){var inp=document.getElementById('surveyInput');var val=inp?inp.value.trim():'';if(!val)return toast('Заполни поле','error');var q=SURVEY_QUESTIONS[state.profile.surveyStep];if(!state.profile.surveyAnswers)state.profile.surveyAnswers={};state.profile.surveyAnswers[q.id]=val;if(q.id==='name')state.profile.name=val;save();playClickSound();nextSurveyStep()}
function nextSurveyStep(){state.profile.surveyStep=(state.profile.surveyStep||0)+1;save();if(state.profile.surveyStep>=SURVEY_QUESTIONS.length)finishSurvey();else renderSurvey()}
function prevSurveyStep(){state.profile.surveyStep=Math.max(0,(state.profile.surveyStep||0)-1);save();renderSurvey()}
function finishSurvey(){var existing=document.getElementById('surveyScreen');if(existing)existing.remove();state.profile.surveyDone=true;state.profile.personalPlan=generatePlan(state.profile.surveyAnswers);save();playLevelUpSound();haptic('success');toast('🎉 Профиль заполнен!','success',4000);checkAchievements();updateHeaderAvatar();navigate('plan')}
function generatePlan(answers){if(!answers)answers={};var plan={days:[],focusDomains:[],metrics:[]};plan.focusDomains=['mental','recovery'];var morning=[{time:'7:30',title:'Пробуждение',desc:'Вода + свет'},{time:'+15 мин',title:'Дыхание 4-7-8',desc:'4 цикла'},{time:'+30 мин',title:'Движение',desc:'Прогулка 15 мин'},{time:'+1 ч',title:'Чтение',desc:'10 страниц'},{time:'+1.5 ч',title:'Deep Work',desc:'90 минут'}];var day=[{time:'12:00',title:'Обед',desc:'Белок + овощи'},{time:'14:00',title:'Медитация',desc:'10 минут'},{time:'15:00',title:'Deep Work #2',desc:'50 минут'},{time:'17:00',title:'Прогулка',desc:'20 минут'}];var evening=[{time:'19:00',title:'Ужин',desc:'Легкий'},{time:'20:00',title:'Рефлексия',desc:'Дневник'},{time:'21:00',title:'Без экранов',desc:'Книга'},{time:'22:30',title:'Сон',desc:'18-20°C'}];plan.days=[{title:'🌅 Утро',items:morning},{title:'☀️ День',items:day},{title:'🌙 Вечер',items:evening}];return plan}
function showWelcome(){var overlay=document.createElement('div');overlay.className='welcome-screen';overlay.innerHTML='<div class="welcome-logo">🧠</div><div class="welcome-title">AI Health Ecosystem</div><div class="welcome-sub">5 уровней · 5 модулей · 125 уроков English · 17 путей · Досуг · AI.</div><button class="btn btn-primary btn-block" style="max-width:340px;" onclick="startOnboarding()">Начать</button>';document.body.appendChild(overlay)}
function startOnboarding(){var w=document.querySelector('.welcome-screen');if(w)w.remove();var name=window.__tgName||'';if(!name){var overlay=document.createElement('div');overlay.className='welcome-screen';overlay.innerHTML='<div class="welcome-logo">👤</div><div class="welcome-title">Как тебя зовут?</div><input type="text" class="welcome-input" id="welcome-name" placeholder="Имя" maxlength="30"/><button class="btn btn-primary btn-block mt-4" style="max-width:340px;margin-top:16px;" onclick="finishOnboarding()">Далее</button>';document.body.appendChild(overlay);setTimeout(function(){var i=document.getElementById('welcome-name');if(i)i.focus()},300)}else{state.profile.name=name;state.settings.onboardingDone=true;save();updateHeaderAvatar();renderTabBar();renderDashboard()}}
function finishOnboarding(){var inp=document.getElementById('welcome-name');var name=inp?inp.value.trim():'';if(!name)return toast('Введи имя','error');state.profile.name=name;state.settings.onboardingDone=true;save();var w=document.querySelector('.welcome-screen');if(w)w.remove();updateHeaderAvatar();renderTabBar();renderDashboard();playLevelUpSound();haptic('success');toast('Добро пожаловать, '+name+'!','success')}
function init(){try{applyTheme(state.settings.theme);updateHeaderAvatar();if(!state.profile.name&&!state.settings.onboardingDone){showWelcome();return}if(state.profile.name&&!state.settings.onboardingDone){state.settings.onboardingDone=true;save()}if(!state.profile.name&&window.__tgName){state.profile.name=window.__tgName;save();updateHeaderAvatar()}if(state.tasks.length===0){state.tasks=[{id:uid(),title:'Завершить отчёт',category:'Работа',planned_time:45,actual_time:0,status:'pending',priority:'high',created_at:nowISO()},{id:uid(),title:'Повторить 10 слов',category:'Обучение',planned_time:15,actual_time:0,status:'pending',priority:'medium',created_at:nowISO()},{id:uid(),title:'Дневник: 3 победы',category:'Личное',planned_time:5,actual_time:0,status:'pending',priority:'medium',created_at:nowISO()}];save()}if(!state.englishProgress)state.englishProgress={};if(!state.entertainment)state.entertainment=[];if(!state.watchlist)state.watchlist=[];if(!state.watched)state.watched=[];if(!state.memoryTraining)state.memoryTraining=[];renderTabBar();renderDashboard();var t=today();if(state.stats.lastActiveDay!==t){var y=new Date();y.setDate(y.getDate()-1);state.stats.streak=state.stats.lastActiveDay===y.toISOString().slice(0,10)?(state.stats.streak||0)+1:1;state.stats.lastActiveDay=t;save()}if('requestIdleCallback' in window){requestIdleCallback(function(){try{checkAchievements()}catch(e){}},{timeout:2000})}else{setTimeout(function(){try{checkAchievements()}catch(e){}},1000)}}catch(e){console.error('Init:',e);var app=document.getElementById('app');if(app)app.innerHTML='<div class="empty"><div class="empty-icon">⚠️</div><div class="empty-title">Ошибка</div><div class="empty-text">'+esc(e.message)+'</div></div>'}}
function attachRipple(){document.addEventListener('pointerdown',function(e){var target=e.target.closest('.btn, .list-row, .chip, .tab-item, .task-item, .card, .icon-btn, .avatar-btn, .persona-item, .segmented-item, .level-card, .module-card, .lesson-row, .emoji-pick, .domain-card, .method-card, .course-card, .path-step, .survey-option, .ent-card, .screen-card');if(!target)return;target.classList.add('tap-ripple');var rect=target.getBoundingClientRect();target.style.setProperty('--rx',((e.clientX-rect.left)/rect.width)*100+'%');target.style.setProperty('--ry',((e.clientY-rect.top)/rect.height)*100+'%');target.classList.remove('rippling');void target.offsetWidth;target.classList.add('rippling');setTimeout(function(){target.classList.remove('rippling')},700)},{passive:true})}
